 */
public object FfiConverterTypePdfSession: FfiConverter<PdfSession, Long> {
    override fun lower(value: PdfSession): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): PdfSession {
        return PdfSession(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): PdfSession {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: PdfSession) = 8UL

    override fun write(value: PdfSession, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



