sealed class FieldValue {
    
    data class Text(
        val `value`: kotlin.String) : FieldValue()
        
    {
        

        companion object
    }
    
    data class Check(
        val `checked`: kotlin.Boolean) : FieldValue()
        
    {
        

        companion object
    }
    
    data class Radio(
        val `onState`: kotlin.String?) : FieldValue()
        
    {
        

        companion object
    }
    
    data class Choice(
        val `values`: List<kotlin.String>) : FieldValue()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFieldValue : FfiConverterRustBuffer<FieldValue>{
    override fun read(buf: ByteBuffer): FieldValue {
        return when(buf.getInt()) {
            1 -> FieldValue.Text(
                FfiConverterString.read(buf),
                )
            2 -> FieldValue.Check(
                FfiConverterBoolean.read(buf),
                )
            3 -> FieldValue.Radio(
                FfiConverterOptionalString.read(buf),
                )
            4 -> FieldValue.Choice(
                FfiConverterSequenceString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FieldValue): ULong = when(value) {
        is FieldValue.Text -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`value`)
            )
        }
        is FieldValue.Check -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterBoolean.allocationSize(value.`checked`)
            )
        }
        is FieldValue.Radio -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterOptionalString.allocationSize(value.`onState`)
            )
        }
        is FieldValue.Choice -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceString.allocationSize(value.`values`)
            )
        }
    }

    override fun write(value: FieldValue, buf: ByteBuffer) {
        when(value) {
            is FieldValue.Text -> {
                buf.putInt(1)
                FfiConverterString.write(value.`value`, buf)
                Unit
            }
            is FieldValue.Check -> {
                buf.putInt(2)
                FfiConverterBoolean.write(value.`checked`, buf)
                Unit
            }
            is FieldValue.Radio -> {
                buf.putInt(3)
                FfiConverterOptionalString.write(value.`onState`, buf)
                Unit
            }
            is FieldValue.Choice -> {
                buf.putInt(4)
                FfiConverterSequenceString.write(value.`values`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





