sealed class PdfException: kotlin.Exception() {
    
    /**
     * The bytes are not a PDF this engine can read (or the feature is unsupported).
     */
    class InvalidPdf(
        
        val `detail`: kotlin.String
        ) : PdfException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The document is encrypted and no password was given.
     */
    class PasswordRequired(
        ) : PdfException() {
        override val message
            get() = ""
    }
    
    /**
     * The given password does not open the document.
     */
    class WrongPassword(
        ) : PdfException() {
        override val message
            get() = ""
    }
    
    /**
     * Input or output exceeds a guard-rail limit.
     */
    class TooLarge(
        
        val `detail`: kotlin.String
        ) : PdfException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * A caller argument is out of range (page index, scale).
     */
    class InvalidArgument(
        
        val `detail`: kotlin.String
        ) : PdfException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The engine failed to render a page.
     */
    class Render(
        
        val `detail`: kotlin.String
        ) : PdfException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * A panic was caught inside the Rust side.
     */
    class Panic(
        
        val `detail`: kotlin.String
        ) : PdfException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The operation is not available in this build (feature gated off, or the engine lacks it).
     */
    class Unsupported(
        
        val `detail`: kotlin.String
        ) : PdfException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * Reading or writing bytes failed.
     */
    class Io(
        
        val `detail`: kotlin.String
        ) : PdfException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * A cooperative cancel (optimize, scan clean) was honoured.
     */
    class Cancelled(
        ) : PdfException() {
        override val message
            get() = ""
    }
    
    /**
     * The document's permissions or the caller's credentials do not allow this operation
     * (e.g. removing protection without the owner password, copying text when copying is forbidden).
     */
    class NotPermitted(
        
        val `detail`: kotlin.String
        ) : PdfException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<PdfException> {
        override fun lift(error_buf: RustBuffer.ByValue): PdfException = FfiConverterTypePdfError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypePdfError : FfiConverterRustBuffer<PdfException> {
    override fun read(buf: ByteBuffer): PdfException {
        

        return when(buf.getInt()) {
            1 -> PdfException.InvalidPdf(
                FfiConverterString.read(buf),
                )
            2 -> PdfException.PasswordRequired()
            3 -> PdfException.WrongPassword()
            4 -> PdfException.TooLarge(
