                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: PdfException, buf: ByteBuffer) {
        when(value) {
            is PdfException.InvalidPdf -> {
                buf.putInt(1)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is PdfException.PasswordRequired -> {
                buf.putInt(2)
                Unit
            }
            is PdfException.WrongPassword -> {
                buf.putInt(3)
                Unit
            }
            is PdfException.TooLarge -> {
                buf.putInt(4)
