sealed class SplitSpec {
    
    data class EveryN(
        val `n`: kotlin.UInt) : SplitSpec()
        
    {
        

        companion object
    }
    
    /**
     * Start a new part before each listed page (0-based, ascending, page 0 is implicit).
     */
    data class Before(
        val `pages`: List<kotlin.UInt>) : SplitSpec()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeSplitSpec : FfiConverterRustBuffer<SplitSpec>{
    override fun read(buf: ByteBuffer): SplitSpec {
        return when(buf.getInt()) {
            1 -> SplitSpec.EveryN(
                FfiConverterUInt.read(buf),
                )
            2 -> SplitSpec.Before(
                FfiConverterSequenceUInt.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: SplitSpec): ULong = when(value) {
        is SplitSpec.EveryN -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUInt.allocationSize(value.`n`)
            )
        }
        is SplitSpec.Before -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceUInt.allocationSize(value.`pages`)
            )
        }
    }

    override fun write(value: SplitSpec, buf: ByteBuffer) {
        when(value) {
            is SplitSpec.EveryN -> {
                buf.putInt(1)
                FfiConverterUInt.write(value.`n`, buf)
                Unit
            }
            is SplitSpec.Before -> {
                buf.putInt(2)
                FfiConverterSequenceUInt.write(value.`pages`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






